const d = $json;

const SYSTEM = "You are a market analyst for a luxury watch trading business. From the data, write a short weekly briefing: a one-sentence headline, 4-7 insights (price trends, competitor price changes, cheapest countries to buy, models trading above retail, seasonal patterns, stock that is now over- or under-priced vs market), and 3-5 concrete actions (what to buy, where, what to reprice). Use numbers from the data. If data is thin, say so. Prices are USD. 'new_equiv' prices are converted to new condition.";
const SCHEMA = {
  "type": "object",
  "properties": {
    "headline": {
      "type": "string"
    },
    "insights": {
      "type": "array",
      "items": {
        "type": "string"
      }
    },
    "actions": {
      "type": "array",
      "items": {
        "type": "string"
      }
    }
  },
  "required": [
    "headline",
    "insights",
    "actions"
  ],
  "additionalProperties": false
};
const userContent = `Report data (JSON):\n${JSON.stringify(d)}`;

return {
  json: {
    claude_request: {
      model: 'claude-opus-5',
      max_tokens: 16000,
      fallbacks: 'default',              // if the model declines, Anthropic retries on a fallback model
      system: SYSTEM,
      messages: [{ role: 'user', content: userContent }],
      output_config: {
        effort: 'high',             // low / medium / high: more effort = better answers, more cost
        format: { type: 'json_schema', schema: SCHEMA },
      },
    },
  },
};

// Read Claude's answer. The answer is JSON because we asked for a JSON schema.
const res = $json;
if (res.stop_reason === 'refusal') {
  throw new Error('Claude declined this request: ' + JSON.stringify(res.stop_details || {}));
}
const text = (res.content || []).filter(b => b.type === 'text').map(b => b.text).join('');
if (!text) {
  throw new Error('Claude returned no text: ' + JSON.stringify(res).slice(0, 500));
}
const ai = JSON.parse(text);

// Make text safe to put inside an HTML email
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const money = (n) => n == null || n === '' ? '-' : '$' + Math.round(Number(n)).toLocaleString('en-US');

const d = $('Collect report data').first().json;

// Turn a list of rows into a simple HTML table
function table(title, rows) {
  if (!rows || !rows.length) return `<h4>${esc(title)}</h4><p>No data yet.</p>`;
  const cols = Object.keys(rows[0]);
  const head = cols.map(c => `<th>${esc(c)}</th>`).join('');
  const body = rows.map(r => '<tr>' + cols.map(c => `<td>${esc(r[c])}</td>`).join('') + '</tr>').join('');
  return `<h4>${esc(title)}</h4><table border="1" cellpadding="4" cellspacing="0"
    style="border-collapse:collapse;font-family:Arial;font-size:12px"><tr style="background:#eee">${head}</tr>${body}</table>`;
}

const html = `<h2>${esc(ai.headline)}</h2>
<h3>Insights</h3><ul>${ai.insights.map(i => `<li>${esc(i)}</li>`).join('')}</ul>
<h3>Suggested actions</h3><ul>${ai.actions.map(a => `<li>${esc(a)}</li>`).join('')}</ul>
<hr>
${table('Top deals this week', d.top_deals)}
${table('Competitor price moves', d.competitor_moves)}
${table('Prices by country (last 30 days)', d.country_prices)}
${table('Market vs official retail', d.retail_vs_market)}
${table('Fair prices (new-condition equivalent)', d.fair_prices)}
${table('Your stock vs market', d.stock_vs_market)}
${table('Inventory', d.inventory)}
${table('Seasonality (average by month)', d.seasonality)}`;

return [{ json: { owner_email: d.owner_email, from_email: d.from_email,
                  subject: `Weekly watch market report - ${ai.headline}`, html } }];
